const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved = {}; let storageOK = true;
try { saved = JSON.parse(localStorage.getItem('grammar-map-v1') || '{}') || {}; } catch { storageOK = false; }
const validIds = new Set(lessons.map(l=>l.id));
const state = {done:Array.isArray(saved.done)?saved.done.filter(x=>validIds.has(x)):[],bookmarks:Array.isArray(saved.bookmarks)?saved.bookmarks.filter(x=>validIds.has(x)):[],last:validIds.has(saved.last)?saved.last:'sentence'};
function persist(){try{localStorage.setItem('grammar-map-v1',JSON.stringify(state))}catch{storageOK=false; toast('浏览器无法保存进度，本次仍可正常学习。')}updateProgress()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function updateProgress(){const n=state.done.length;$('#progress-count').textContent=`${n} / ${lessons.length}`;$('#progress-bar').style.width=`${n/lessons.length*100}%`;$('#bookmark-count').textContent=state.bookmarks.length;document.querySelectorAll('.nav-lesson-status').forEach(el=>el.textContent=state.done.includes(el.dataset.lessonId)?'✓':'')}
function chapterNav(){
 $('#chapter-nav').innerHTML=chapters.map((c,i)=>`<details class="nav-group" data-chapter="${c.id}"><summary><span class="chapter-number">0${i+1}</span><span>${esc(c.name)}</span><span class="nav-chevron" aria-hidden="true">›</span></summary><div class="nav-lessons"><a class="nav-overview" href="#chapter/${c.id}" data-chapter-link="${c.id}">本章概览</a>${lessons.filter(l=>l.chapter===i).map(l=>`<a href="#lesson/${l.id}" data-lesson-link="${l.id}"><span>${esc(l.title)}</span><span class="nav-lesson-status" data-lesson-id="${l.id}" aria-hidden="true">${state.done.includes(l.id)?'✓':''}</span></a>`).join('')}</div></details>`).join('');
}
function syncChapterNav(type,id){
 const current=type==='chapter'?id:type==='lesson'?chapters[lessons.find(l=>l.id===id)?.chapter]?.id:null;
 document.querySelectorAll('.nav-group').forEach(group=>{const active=group.dataset.chapter===current;group.classList.toggle('current',active);if(active)group.open=true;});
 document.querySelectorAll('[data-lesson-link],[data-chapter-link]').forEach(a=>{const active=type==='lesson'?a.dataset.lessonLink===id:type==='chapter'?a.dataset.chapterLink===id:false;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
}
function lessonRows(items){return items.map(l=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="lesson-status ${state.done.includes(l.id)?'complete':''}">${state.done.includes(l.id)?'✓':String(lessons.indexOf(l)+1).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong></span><span class="row-arrow">↗</span></a>`).join('')}
let activeAtlas=null;
function renderGrammarHome(){const next=lessons.find(l=>!state.done.includes(l.id))||lessons[0];$('#main').innerHTML=`<section class="compact-home"><div class="compact-heading"><h1>英语语法</h1><a class="button primary" href="#lesson/${next.id}">${state.done.length?'继续学习':'开始学习'} →</a></div>${grammarFramework()}<h2 class="directory-heading">全部主题</h2><div id="map" class="chapter-grid">${chapters.map((c,i)=>{const group=lessons.filter(l=>l.chapter===i);return `<section class="chapter-card ${c.color}"><a class="compact-chapter-title" href="#chapter/${c.id}"><span class="chapter-icon">${c.icon}</span><h2>${c.name}</h2><span>→</span></a><div class="compact-topics">${group.map(l=>`<a href="#lesson/${l.id}">${esc(l.title)}<span>${state.done.includes(l.id)?'✓':'›'}</span></a>`).join('')}</div></section>`}).join('')}</div></section>`;activeAtlas?.destroy();activeAtlas=mountAtlas($('.atlas'));}
function renderChapter(id){const i=chapters.findIndex(c=>c.id===id);if(i<0)return notFound();const c=chapters[i];$('#breadcrumb').textContent=c.name;$('#main').innerHTML=`<div class="reading-wrap"><a class="back-link" href="#grammar">← 全部章节</a><h1 class="page-title">${c.name}</h1><div class="chapter-lessons">${lessonRows(lessons.filter(l=>l.chapter===i))}</div></div>`}
function tenseTable(){return `<section class="lesson-section"><h2>时态速查</h2><p>完成：强调此前的结果；完成进行：强调持续的过程。</p><div class="table-scroll"><table><caption>教学中常见的十二种时间与状态组合</caption><thead><tr><th>时间视角</th><th>一般</th><th>进行</th><th>完成</th><th>完成进行</th></tr></thead><tbody>${tenseGrid.map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><p class="caption">将来表达并非独立的动词时态词形；这是一种方便入门的教学分类。</p></section>`}
function exampleList(items){return items.map(e=>`<div class="example"><div><p class="english-example" lang="en">${esc(e[0])}</p><p class="translation">${esc(e[1])}</p><p class="example-detail">${esc(e[2])}</p></div></div>`).join('')}
function lessonTable(table){return `<div class="table-scroll"><table class="verb-reference"><thead><tr>${table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function renderLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return notFound();state.last=id;persist();const n=lessons.indexOf(l),c=chapters[l.chapter];$('#breadcrumb').textContent=l.title;$('#main').innerHTML=`<div class="lesson-layout"><article class="lesson-content"><div class="compact-lesson-head"><a class="back-link" href="#chapter/${c.id}">← ${c.name}</a><button id="bookmark" class="bookmark-button" aria-pressed="${state.bookmarks.includes(id)}">${state.bookmarks.includes(id)?'★ 已收藏':'☆ 收藏'}</button></div><h1 class="page-title">${l.title}</h1>
<section class="lesson-section compact-rules" id="understand"><h2>${esc(l.introHeading)}</h2><p class="lesson-explanation">${esc(l.explain)}</p><div class="pattern"><strong>${l.pattern}</strong></div></section>
${id==='sentence'?`<div class="sentence-builder"><div><button data-part="subject">We<small>主语</small></button><button data-part="verb">study<small>谓语</small></button><button data-part="object">English<small>宾语</small></button><button data-part="adverbial">at home.<small>地点状语</small></button></div><p id="part-explanation" aria-live="polite">点击单词查看成分</p></div>`:''}
${comparisonContent(l,'usage')}
${l.omitExamples?'':l.sections?l.sections.map(section=>`<section class="lesson-section topic-section"><h2>${esc(section.title)}</h2><p>${esc(section.paragraph)}</p>${section.table?lessonTable(section.table):''}<div class="examples">${exampleList(section.examples.map(i=>l.examples[i]))}</div></section>`).join(''):`<section class="lesson-section" id="examples"><h2>例句</h2><div class="examples">${exampleList(l.examples.slice(0,3))}</div></section>`}
${l.reference?`<section class="lesson-section"><h2>${esc(l.reference.title)}</h2><div class="table-scroll"><table class="verb-reference"><thead><tr>${l.reference.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${l.reference.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`:''}
${comparisonContent(l,'pairs')}
<div class="compact-tip" id="tip"><strong>注意</strong><span>${esc(l.shortTip)}</span></div>
<details class="extra-details"><summary>补充说明</summary>${l.examples.slice(l.mainExampleCount||3).map(e=>`<div class="extra-example"><strong lang="en">${esc(e[0])}</strong><p>${esc(e[1])}</p><p>${e[2]}</p></div>`).join('')}<p>${l.tip}</p>${id==='future'?tenseTable():''}${l.source?`<a class="source-link" href="${esc(l.source[1])}" target="_blank" rel="noopener noreferrer">${esc(l.source[0])} ↗</a>`:''}${l.usageGuide?l.usageGuide.sources.map(([label,url])=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`).join(''):''}</details>
${l.related?`<nav class="related-lessons" aria-label="相关知识">${l.related.map(id=>{const item=lessons.find(x=>x.id===id);return `<a href="#lesson/${id}">${esc(item.title)} →</a>`}).join('')}</nav>`:''}
<section class="lesson-section quiz" id="practice" aria-label="本节练习"></section>
<details class="own-sentence"><summary>自己造句</summary><textarea id="sentence-draft" rows="2" placeholder="写一句英语…" aria-label="我的造句草稿"></textarea><span id="draft-status" aria-live="polite">本地保存 · 不自动批改</span></details>
<div class="lesson-end"><button class="button primary" id="complete">${state.done.includes(id)?'✓ 已读':'标记已读'}</button></div><div class="lesson-pagination">${n?`<a href="#lesson/${lessons[n-1].id}"><small>← 上一节</small>${lessons[n-1].title}</a>`:'<span></span>'}${n<lessons.length-1?`<a href="#lesson/${lessons[n+1].id}"><small>下一节 →</small>${lessons[n+1].title}</a>`:'<a href="#grammar">回到目录 →</a>'}</div></article></div>`;
 $('#bookmark').onclick=()=>{state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();const b=$('#bookmark');b.textContent=state.bookmarks.includes(id)?'★ 已收藏':'☆ 收藏';b.setAttribute('aria-pressed',String(state.bookmarks.includes(id)))};
 $('#complete').onclick=()=>{const done=state.done.includes(id);state.done=done?state.done.filter(x=>x!==id):[...state.done,id];persist();$('#complete').textContent=done?'标记已读':'✓ 已读';toast(done?'已取消已读':'已读')};
 mountPractice($('#practice'),l.quizzes,{onAnswer:(i,c,q)=>recordQuizMistake('grammar',id,i,c,q)});
 const partText={subject:'We：主语，谁在学习。',verb:'study：谓语动词，做什么。',object:'English：宾语，学习什么。',adverbial:'at home：介词短语，作地点状语，补充在哪里学习；We study English 本身已经完整。'};
 document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{$('#part-explanation').textContent=partText[b.dataset.part]});
 document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth',block:'start'})});
 try{$('#sentence-draft').value=localStorage.getItem('grammar-draft-'+id)||''}catch{};
 $('#sentence-draft').oninput=()=>{try{localStorage.setItem('grammar-draft-'+id,$('#sentence-draft').value);$('#draft-status').textContent='✓ 草稿已保存'}catch{$('#draft-status').textContent='无法保存，请自行复制草稿'}};
}
function renderReview(){$('#breadcrumb').textContent='收藏';$('#main').innerHTML=`<div class="reading-wrap"><h1 class="page-title">收藏</h1>${state.bookmarks.length?`<div class="chapter-lessons">${lessonRows(lessons.filter(l=>state.bookmarks.includes(l.id)))}</div>`:'<div class="empty-state"><p>暂无收藏</p><a class="button primary" href="#grammar">浏览语法 →</a></div>'}</div>`}
function renderReferences(){$('#breadcrumb').textContent='参考与说明';$('#main').innerHTML=`<div class="reading-wrap"><a class="back-link" href="#">← 返回地图</a><div class="eyebrow">ABOUT THIS HANDBOOK</div><h1 class="page-title">先理解，再慢慢深入。</h1><p class="page-lead">面向中文学习者的英语读写练习与语法参考。</p><div class="prose"><h2>范围与学习顺序</h2><p>这里覆盖句子骨架、常见词类、动词时间表达、语态、句式、从句与非谓语等主要板块，提供体系概览与起步例句。它不是穷尽所有例外的参考语法书，也不等同于完整的英语能力课程。基础章节可按顺序学，进阶章节先知道“有这回事”即可。</p><h2>讲解与例句</h2><p>中文讲解与例句为本站编写。部分规则作了面向初学者的简化，并注明常见边界。遇到复杂语境，可继续查阅以下参考资料。</p><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference">British Council · English grammar reference ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2">British Council · A1–A2 grammar ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://dictionary.cambridge.org/grammar/british-grammar/">Cambridge Dictionary · English Grammar Today ↗</a><h2>关于学习记录</h2><p>已读、收藏、复习记录和写作草稿仅保存在当前浏览器，不会跨设备同步。清理浏览器数据会清除这些记录，可在学习首页导出备份。本站没有接入 AI，也不会将练习或草稿发送到服务器。</p></div></div>`}
function notFound(){$('#main').innerHTML='<div class="reading-wrap empty-state"><h1>这一页没有找到。</h1><a class="button primary" href="#">回到语法地图</a></div>'}
function render(){const hash=location.hash.slice(1);activeAtlas?.destroy();activeAtlas=null;$('#breadcrumb').textContent='英语语法';const [type,id]=hash.split('/');syncStudyNavigation(type,id);document.querySelectorAll('.main-nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav===(type==='review'?'review':type==='lesson'?'lesson':'home')));syncChapterNav(type,id);if(type==='lesson')renderLesson(id);else if(type==='chapter')renderChapter(id);else if(type==='review')renderReview();else if(type==='references')renderReferences();else if(type==='grammar'||type==='map')renderGrammarHome();else if(type==='reading'||type==='writing')renderStudyCatalog(type);else if(type==='read')renderReading(id);else if(type==='write')renderWriting(id);else if(type==='vocabulary')renderVocabulary(id);else if(type==='revision')renderRevision();else if(!hash)renderPortal();else notFound();document.title=`${$('#breadcrumb').textContent} · 从句子开始`;document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,left:0,behavior:"instant"});updateProgress()}
function search(){const query=$('#search-input').value.trim().toLowerCase();const results=query?lessons.filter(l=>[l.title,l.en,l.summary,l.explain,l.pattern,...l.examples.flat()].join(' ').toLowerCase().includes(query)):lessons.slice(0,4);const reading=query?readingUnits.filter(u=>[u.title,u.genre,...u.paragraphs.map(p=>p.en),...u.phrases.flat()].join(' ').toLowerCase().includes(query)):readingUnits.slice(0,2);const vocabularyResults=query?vocabularyBank.filter(e=>[e.en,e.meaning,e.note].join(' ').toLowerCase().includes(query)).slice(0,12):[];$('#search-results').innerHTML=`<p class="search-label">${query?`显示 ${results.length+reading.length+vocabularyResults.length} 个相关内容`:'从这里开始'}</p>${results.map(l=>`<a class="search-result" href="#lesson/${l.id}"><span><strong>${esc(l.title)}</strong><small>语法 · ${esc(l.en)}</small></span><span>↗</span></a>`).join('')}${reading.map(u=>`<a class="search-result" href="#read/${u.id}"><span><strong>${esc(u.title)}</strong><small>阅读 · ${esc(readingLevels[u.level].name)}</small></span><span>↗</span></a>`).join('')}${vocabularyResults.map(e=>`<a class="search-result" href="#vocabulary/${encodeURIComponent(e.id)}"><span><strong>${esc(e.en)}</strong><small>词汇与搭配 · ${esc(e.meaning)}</small></span><span>↗</span></a>`).join('')}${!results.length&&!reading.length&&!vocabularyResults.length?'<p class="search-empty">没有匹配结果。</p>':''}`;document.querySelectorAll('.search-result').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
function openSearch(){search();$('#search-dialog').showModal();$('#search-input').focus()}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({behavior:'instant'})};
$('#search-trigger').onclick=openSearch;$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=search;$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close()};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#search-dialog').open){e.preventDefault();openSearch()}});
$('#menu-toggle').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')))};
window.addEventListener('hashchange',render);chapterNav();render();if(!storageOK)toast('当前浏览器的本地保存不可用。');
